const $=s=>document.querySelector(s),C=Calc,f=n=>n===null?'Không xác định':Number(n.toFixed(4)).toString(),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),list=a=>a.map(f).join(', '),set=a=>'{'+a.map(esc).join(', ')+'}',table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`,heading=(n,t)=>`<div class="section-heading"><span class="step">${n}</span><h3>${t}</h3></div>`,formula=t=>`<div class="formula">${t}</div>`,note=t=>`<div class="note">${t}</div>`;
const commonX=[5.1,4.9,4.6,5.7,5.4,5.1,5.1,5.3,5,7,6.4,4.5],commonY=[3.5,3,3.1,4.4,3.9,3.5,3.8,3.7,3.3,3.2,3.2,2.3],tx=[['F','M','B','E'],['O','F','E'],['O','A','H','S'],['D','B','F','E'],['D','A','H','S'],['O','M','E'],['O','A','D','H','S']];
const exams=[{x:[7,4.5,5.5,6.5,6.1,5.3,5,5.1,4.9,4.6,5.7,5.4],y:[3.2,2.3,3.5,2.8,2.8,3.7,3.3,3.5,3,3.1,4.4,3.9],norm:'mad',bin:'depth',smooth:'boundaries',points:[[5,3],[15,12],[10,15],[24,10],[30,45],[85,70],[71,80],[60,78],[55,52],[80,91]],initial:[0,2],distance:'euclidean',name:'Thống kê & K-means',single:true},{x:commonX,y:commonY,norm:'minmax',bin:'depth',smooth:'means',tx,support:40,name:'Chuẩn hóa & Apriori',single:true},{x:[6.4,4.5,5.1,4.9,4.6,5.7,5.4,5.1,5.1,5.3,5,7],y:[3.2,2.3,3.5,3,3.1,4.4,3.9,3.5,3.8,3.7,3.3,3.2],norm:'std',bin:'width',smooth:'means',points:[[1,2],[2,5],[8,4],[5,8],[7,5],[2,10],[6,4]],initial:[0,3,5],distance:'manhattan',name:'Z-score & Manhattan',single:true},{x:[9.1,4.5,5.3,6.7,6.5,7,6,5.5,7,7,8.5,8.6],y:[8.5,5.5,6,7.5,8.5,6,6.5,6.8,9,7.2,8,8.5],norm:'std',bin:'width',smooth:'means',tx:[['I6','I1','I3'],['I1','I2','I4','I5','I3'],['I3','I2','I5'],['I6','I7'],['I1','I3','I2','I4','I5']],support:60,name:'Phân thùng & Apriori',onlyY:true,binX:true},{x:commonX,y:commonY,norm:'minmax',bin:'depth',smooth:'means',tx,support:40,name:'Min-max & luật kết hợp'}];
let exam=0,tab=0,view='exam';const drafts={};
function save(){try{localStorage.setItem('kpdl-state',JSON.stringify({exam,tab,drafts}))}catch{}}
try{const s=JSON.parse(localStorage.getItem('kpdl-state'));if(s&&Number.isInteger(s.exam)&&s.exam>=0&&s.exam<5){exam=s.exam;tab=s.tab||0;Object.assign(drafts,s.drafts||{})}}catch{}
function parseNumbers(s){const a=s.trim().split(/[\s,;]+/).map(Number);if(a.length<2||a.length>500||a.some(x=>!Number.isFinite(x)))throw Error('Nhập từ 2 đến 500 số hợp lệ, ngăn cách bằng dấu phẩy hoặc khoảng trắng.');return a}
function guarded(fn){try{fn()}catch(e){$('#output').innerHTML=`<div class="error" role="alert">${esc(e.message)}</div>`}}
function render(){const e=exams[exam];$('#exams').innerHTML=exams.map((e,i)=>`<button data-exam="${i}" class="${view==='exam'&&exam===i?'active':''}">▧ &nbsp; Đề số ${i+1}<small>${e.name}</small></button>`).join('');document.querySelectorAll('[data-exam]').forEach(b=>b.onclick=()=>{exam=+b.dataset.exam;tab=0;view='exam';save();render()});document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',view===b.dataset.view);b.onclick=()=>{view=b.dataset.view;render()}});$('#source').style.display=view==='exam'?'':'none';$('#source').href=`assets/${exam+1}.png`;$('#title').textContent=view==='exam'?`Đề số ${exam+1} · ${e.name}`:view==='id3'?'Cây quyết định ID3':'Khai thác FP-Growth';$('#description').textContent=view==='exam'?'Dữ liệu từ đề gốc · Có thể chỉnh sửa và tính lại':'Dữ liệu và thuật toán từ kpdl.ipynb';const tabs=view==='exam'?['Câu 1 · Phân tích dữ liệu',e.points?'Câu 2 · K-means':'Câu 2 · Apriori']:[];if(tab>=tabs.length)tab=0;$('#tabs').innerHTML=tabs.map((t,i)=>`<button data-tab="${i}" class="${tab===i?'active':''}">${t}</button>`).join('');document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=+b.dataset.tab;save();render()});if(view==='id3')return renderID3();if(view==='fp')return renderAssociation(true);if(tab===0)renderStats();else if(tab===1)e.points?renderKmeans():renderAssociation(false);}
function boxplot(a,name){const s=C.stats(a),min=Math.min(...a),max=Math.max(...a),pad=(max-min)*.12||1,scale=v=>60+(v-min+pad)/(max-min+2*pad)*580;return `<svg class="chart" viewBox="0 0 700 150" role="img" aria-label="Boxplot ${name}"><text x="25" y="27">${name} · Boxplot</text><line x1="60" x2="640" y1="115" y2="115" stroke="#dce6df"/><line x1="${scale(s.low)}" x2="${scale(s.high)}" y1="68" y2="68" stroke="#659276"/><rect x="${scale(s.q1)}" y="45" width="${scale(s.q3)-scale(s.q1)}" height="46" fill="#e0eee4" stroke="#659276"/><line x1="${scale(s.median)}" x2="${scale(s.median)}" y1="45" y2="91" stroke="#2e6748" stroke-width="3"/>${[s.low,s.high].map(v=>`<line x1="${scale(v)}" x2="${scale(v)}" y1="55" y2="81" stroke="#659276"/>`).join('')}${s.outliers.map(v=>`<circle cx="${scale(v)}" cy="68" r="4" fill="#cd9b55"/>`).join('')}${[...new Set([min,s.q1,s.median,s.q3,max])].map(v=>`<text x="${scale(v)}" y="135" text-anchor="middle">${f(v)}</text>`).join('')}</svg>`}
function renderStats(){const e=exams[exam],d=drafts['stats'+exam]||{};$('#content').innerHTML=`<div class="input-grid"><label>Dãy X<textarea id="x">${esc(d.x||e.x.join(', '))}</textarea></label><label>Dãy Y<textarea id="y">${esc(d.y||e.y.join(', '))}</textarea></label></div><div class="controls"><label>Chữ số cuối MSSV<input id="digit" type="number" min="0" max="9" value="${d.digit??7}"></label><button class="primary" id="calculate">Tính lời giải ↗</button><button class="secondary" id="reset">Khôi phục đề gốc</button></div><div id="output" aria-live="polite"></div>`;$('#calculate').onclick=()=>guarded(()=>{const x=parseNumbers($('#x').value),y=parseNumbers($('#y').value),digit=Number($('#digit').value);if(x.length!==y.length)throw Error('X và Y phải có cùng số phần tử để tính tương quan.');if(!Number.isInteger(digit)||digit<0||digit>9)throw Error('Chữ số cuối MSSV phải là số nguyên từ 0 đến 9.');if(e.single&&digit>=x.length)throw Error('Vị trí MSSV + 1 vượt quá số phần tử.');drafts['stats'+exam]={x:$('#x').value,y:$('#y').value,digit};save();const sx=C.stats(x),sy=C.stats(y),p=C.pearson(x,y);let html=note(`Đang giải theo đề ${exam+1}: ${e.norm==='minmax'?'Min-max [1, 5]':e.norm==='mad'?'Z-score với độ lệch tuyệt đối trung bình':'Z-score với độ lệch chuẩn tổng thể'} · ${e.bin==='depth'?'Equal-depth':'Equal-width'}, 3 bin · ${e.smooth==='means'?'Làm trơn trung bình':'Làm trơn biên'}.`)+heading('a','Trung bình, trung vị và mode')+table(['Biến','Số phần tử','Trung bình','Trung vị','Mode'],[['X',x.length,f(sx.mean),f(sx.median),sx.mode.length?list(sx.mode):'Không có'],['Y',y.length,f(sy.mean),f(sy.median),sy.mode.length?list(sy.mode):'Không có']])+formula('x̄ = Σxᵢ / n; trung vị = trung bình hai giá trị giữa khi n chẵn; mode = giá trị có tần số lớn nhất.')+heading('b','Boxplot và phát hiện ngoại lệ')+note('Q1, Q3 là trung vị của hai nửa dãy đã sắp xếp (bỏ trung vị nếu n lẻ). Râu kéo tới giá trị thực nằm trong [Q1 − 1.5 IQR, Q3 + 1.5 IQR].')+`<div class="${e.onlyY?'':'two-col'}">${e.onlyY?'':boxplot(x,'X')}${boxplot(y,'Y')}</div>`+table(['Biến','Q1','Q2','Q3','IQR','Ngoại lệ'],(e.onlyY?[['Y',sy]]:[['X',sx],['Y',sy]]).map(([n,s])=>[n,f(s.q1),f(s.median),f(s.q3),f(s.iqr),s.outliers.length?list(s.outliers):'Không có']))+heading('c',`Chuẩn hóa ${e.onlyY?'Y':'X và Y'}`);
for(const [name,a,s]of(e.onlyY?[['Y',y,sy]]:[['X',x,sx],['Y',y,sy]])){const divisor=e.norm==='minmax'?Math.max(...a)-Math.min(...a):s[e.norm];if(divisor===0){html+=note(`${name}: Không thể chuẩn hóa vì mẫu số bằng 0 (dãy hằng).`);continue}const normalized=a.map(v=>e.norm==='minmax'?1+(v-Math.min(...a))/divisor*4:(v-s.mean)/divisor);html+=formula(e.norm==='minmax'?`${name}′ = 1 + (${name} − ${f(Math.min(...a))}) / (${f(Math.max(...a))} − ${f(Math.min(...a))}) × 4`:`${name}: μ = ${f(s.mean)}; ${e.norm==='mad'?'MAD = Σ|xᵢ − μ| / n':'σ = √(Σ(xᵢ − μ)² / n)'} = ${f(divisor)}; zᵢ = (xᵢ − μ) / ${f(divisor)}`);if(e.single)html+=note(`i = ${digit} + 1 = ${digit+1}. ${name}[${digit+1}] = ${f(a[digit])} → ${e.norm==='minmax'?`1 + (${f(a[digit])} − ${f(Math.min(...a))}) / ${f(divisor)} × 4`:`(${f(a[digit])} − ${f(s.mean)}) / ${f(divisor)}`} = <b>${f(normalized[digit])}</b>.`);html+=table(['Vị trí',...a.map((_,i)=>i+1)],[['Giá trị gốc',...a.map(f)],['Chuẩn hóa',...normalized.map(v=>`<span class="result">${f(v)}</span>`)]])}
html+=heading('d','Chia 3 bin và làm trơn')+note(e.bin==='depth'?'Sắp tăng dần, chia thành 3 bin gần bằng số phần tử; bin đầu nhận phần tử dư.':'Độ rộng w = (max − min) / 3. Quy ước bin đầu [a, b], các bin sau (a, b], khớp notebook.');if(e.smooth==='boundaries')html+=note('Thay mỗi giá trị bằng biên gần nhất của bin. Nếu cách đều hai biên, chọn biên dưới.');for(const[name,a]of(e.binX?[['X',x]]:[['X',x],['Y',y]])){html+=formula(`${name} tăng dần: [${list([...a].sort((a,b)=>a-b))}]`);if(e.bin==='width')html+=formula(`w = (${f(Math.max(...a))} − ${f(Math.min(...a))}) / 3 = ${f((Math.max(...a)-Math.min(...a))/3)}`);html+=table([name+' · Bin','Khoảng','Giá trị','Cách tính','Sau làm trơn'],C.bins(a,3,e.bin,e.smooth).map((b,i)=>[i+1,b.range?`${i===0?'[':'('}${list(b.range)}]`:'Theo thứ tự',list(b.values)||'Rỗng',b.values.length?(e.smooth==='means'?`(${b.values.map(f).join(' + ')}) / ${b.values.length} = ${f(C.mean(b.values))}`:`Biên: ${f(b.values[0])}, ${f(b.values.at(-1))}`):'—',list(b.smoothed)||'—']))}html+=heading('e','Hệ số tương quan Pearson')+formula(`r = Σ(xᵢ − x̄)(yᵢ − ȳ) / √[Σ(xᵢ − x̄)² × Σ(yᵢ − ȳ)²] = ${f(p.numerator)} / √(${f(p.sx)} × ${f(p.sy)})`)+note(p.r===null?'Không xác định vì ít nhất một dãy có phương sai bằng 0.':`r = <b>${f(p.r)}</b>. ${Math.abs(p.r)<.1?'Tương quan tuyến tính rất yếu.':`Tương quan ${p.r>0?'thuận':'nghịch'}; |r| = ${f(Math.abs(p.r))}.`} Tương quan không chứng minh quan hệ nhân quả.`);$('#output').innerHTML=html});$('#reset').onclick=()=>{delete drafts['stats'+exam];save();renderStats()};$('#calculate').click()}
function scatter(points,h){const palette=['#497c60','#d29b57','#6b8fbc','#a078a5'],all=[...points,...h.next],xs=all.map(p=>p[0]),ys=all.map(p=>p[1]),minx=Math.min(...xs),miny=Math.min(...ys),dx=Math.max(...xs)-minx||1,dy=Math.max(...ys)-miny||1,X=v=>50+(v-minx)/dx*560,Y=v=>230-(v-miny)/dy*195;return `<svg viewBox="0 0 680 270" class="chart" role="img" aria-label="Biểu đồ phân cụm"><path d="M40 20 V240 H640" stroke="#d4dfd8" fill="none"/><text x="20" y="25">Y</text><text x="650" y="243">X</text>${points.map((p,i)=>`<circle cx="${X(p[0])}" cy="${Y(p[1])}" r="5" fill="${palette[h.labels[i]%4]}"/><text x="${X(p[0])+8}" y="${Y(p[1])-6}">A${i+1}</text>`).join('')}${h.next.map((p,i)=>`<text x="${X(p[0])}" y="${Y(p[1])+6}" text-anchor="middle" style="fill:${palette[i%4]};font-size:25px">✚</text>`).join('')}<text x="50" y="262">Điểm tròn: quan sát · Dấu cộng: tâm mới · X: ${f(minx)}–${f(minx+dx)} · Y: ${f(miny)}–${f(miny+dy)}</text></svg>`}
function renderKmeans(){const e=exams[exam];$('#content').innerHTML=`<div class="input-grid"><label>Tọa độ · Mỗi dòng một điểm (x, y)<textarea id="points" rows="7">${e.points.map(p=>p.join(', ')).join('\n')}</textarea></label><div><label>Tâm ban đầu · Số thứ tự điểm, bắt đầu từ 1<input id="centers" value="${e.initial.map(i=>i+1).join(', ')}"></label><label>Khoảng cách<select id="distance"><option value="euclidean" ${e.distance==='euclidean'?'selected':''}>Euclidean</option><option value="manhattan" ${e.distance==='manhattan'?'selected':''}>Manhattan</option></select></label></div></div><button class="primary" id="run">Chạy K-means ↗</button><div id="output" aria-live="polite"></div>`;$('#run').onclick=()=>guarded(()=>{const points=$('#points').value.trim().split('\n').map(parseNumbers);if(points.length>100||points.some(p=>p.length!==2))throw Error('Nhập tối đa 100 điểm, mỗi dòng đúng 2 tọa độ.');const ids=parseNumbers($('#centers').value).map(n=>n-1);if(ids.length>10||new Set(ids).size!==ids.length||ids.some(i=>!Number.isInteger(i)||i<0||i>=points.length))throw Error('Chọn 2–10 tâm khác nhau bằng số thứ tự điểm hợp lệ.');const method=$('#distance').value,h=C.kmeans(points,ids.map(i=>points[i]),method),last=h.at(-1);let html=note(`K = ${ids.length} · ${method==='euclidean'?'d(P,C) = √Σ(pᵢ − cᵢ)²':'d(P,C) = Σ|pᵢ − cᵢ|'} · Nếu hòa khoảng cách, chọn cụm có số thứ tự nhỏ hơn. Tâm cập nhật bằng trung bình cộng theo notebook và yêu cầu K-means; với Manhattan, đây không phải K-medians.`)+scatter(points,last)+note(`${last.stable?'Đã hội tụ':'Đạt giới hạn 100 vòng, chưa xác nhận hội tụ'} sau ${h.length} vòng. `)+table(['Cụm','Các điểm','Tâm cuối'],last.next.map((c,j)=>['C'+(j+1),points.map((_,i)=>last.labels[i]===j?'A'+(i+1):'').filter(Boolean).join(', ')||'Rỗng','('+list(c)+')']));h.forEach((s,i)=>{html+=`<details ${i===0?'open':''}><summary>Vòng ${i+1} · ${s.stable?'Nhãn cụm không đổi → hội tụ':'Gán cụm và cập nhật tâm'}</summary>`+formula(s.centers.map((c,j)=>`C${j+1} = (${list(c)})`).join(' · '))+table(['Điểm',...s.centers.map((_,j)=>'d(C'+(j+1)+')'),'Gán cụm'],points.map((p,j)=>['A'+(j+1)+' ('+list(p)+')',...s.distances[j].map(f),`<b class="result">C${s.labels[j]+1}</b>`]));s.next.forEach((c,j)=>{const members=points.filter((_,i)=>s.labels[i]===j);html+=formula(members.length?`C${j+1} mới = (${c.map((_,d)=>'('+members.map(p=>f(p[d])).join(' + ')+') / '+members.length).join(', ')}) = (${list(c)})`:`C${j+1} rỗng → giữ nguyên tâm (${list(c)}).`)});html+='</details>'});$('#output').innerHTML=html});$('#run').click()}
function treeHTML(node){return `<li><b>${esc(node.item)}</b>${node.parent?': '+node.count:''}${node.children.length?`<ul>${node.children.map(treeHTML).join('')}</ul>`:''}</li>`}
function renderAssociation(fp){const e=exams[exam],transactions=fp?tx:e.tx;$('#content').innerHTML=`<label>Giao dịch · Mỗi dòng một giao dịch, các mục ngăn cách bằng dấu phẩy<textarea id="transactions" rows="7">${transactions.map(t=>t.join(', ')).join('\n')}</textarea></label><div class="controls"><label>Minsup (%)<input id="support" type="number" min="1" max="100" value="${fp?40:e.support}"></label><label>Minconf (%)<input id="confidence" type="number" min="0" max="100" value="75"></label><button class="primary" id="mine">${fp?'Chạy FP-Growth':'Tìm tập phổ biến & luật'} ↗</button></div><div id="output" aria-live="polite"></div>`;$('#mine').onclick=()=>guarded(()=>{const transactions=$('#transactions').value.trim().split('\n').map(line=>[...new Set(line.trim().split(/[\s,;]+/).filter(Boolean))]),support=Number($('#support').value),confidence=Number($('#confidence').value);if(!transactions.length||transactions.some(t=>!t.length)||transactions.length>200||new Set(transactions.flat()).size>12)throw Error('Nhập 1–200 giao dịch, tối đa 12 mục khác nhau để lời giải giữ gọn.');if(!Number.isFinite(support)||support<=0||support>100||!Number.isFinite(confidence)||confidence<0||confidence>100)throw Error('Minsup thuộc (0, 100], minconf thuộc [0, 100].');const a=C.apriori(transactions,support,confidence);let html=note(`N = ${transactions.length}; min_count = ⌈${transactions.length} × ${f(support)} / 100⌉ = <b>${a.threshold}</b>. Support(X) = Count(X) / N × 100%.`)+table(['ID','Các mục'],transactions.map((t,i)=>['T'+(i+1),t.map(esc).join(', ')]));if(fp){const r=C.fpGrowth(transactions,support);html+=heading('1','Sắp mục và xây FP-Tree')+formula('Thứ tự tần suất giảm dần, hòa thì theo tên: '+r.order.map(esc).join(' → '))+table(['Giao dịch','Sau lọc và sắp thứ tự'],transactions.map((t,i)=>['T'+(i+1),r.order.filter(x=>t.includes(x)).map(esc).join(' → ')||'∅']))+`<div class="tree"><ul>${treeHTML(r.root)}</ul></div>`+heading('2','Conditional Pattern Base')+table(['Hậu tố','Các đường dẫn có trọng số'],r.bases.map(b=>[set(b.suffix),b.base.map(t=>`⟨${t.items.map(esc).join(', ')}⟩: ${t.weight}`).join('; ')||'∅']));}else{html+=heading('1','Sinh ứng viên Ck và lọc tập phổ biến Lk');for(const step of a.history)html+=`<details open><summary>C${step.k} → L${step.k}</summary>`+table(['Tập mục','Count','Support','Đạt minsup?'],step.rows.map(r=>[set(r.items),r.count,f(r.count/transactions.length*100)+'%',r.count>=a.threshold?'<b class="result">Giữ lại</b>':'Loại']))+'</details>';html+=note('Kết thúc khi không còn tập ứng viên đạt ngưỡng hoặc không thể sinh thêm ứng viên. Mọi tập con k − 1 của ứng viên Ck phải thuộc Lk.');}html+=heading('3','Tổng hợp tập phổ biến')+table(['Tập mục','Count','Support'],a.freq.map(r=>[set(r.items),r.count,f(r.count/transactions.length*100)+'%']))+heading('4','Luật kết hợp mạnh')+formula('Confidence(A → B) = Count(A ∪ B) / Count(A) × 100%. Support(A → B) = Support(A ∪ B).')+note(`Có <b>${a.rules.filter(r=>r.strong).length}</b> luật đạt minconf ${f(confidence)}%. Các luật dưới đây được sinh từ tập phổ biến, nên đã đạt minsup.`)+table(['Luật','Support','Cách tính confidence','Kết luận'],a.rules.map(r=>[set(r.a)+' → '+set(r.b),f(r.support)+'%',`${r.count} / ${r.den} × 100 = ${f(r.confidence)}%`,r.strong?'<b class="result">Luật mạnh</b>':'Không đạt minconf']));$('#output').innerHTML=html});$('#mine').click()}
function renderID3(){const rows=[['Nang','Nong','Cao','Yeu','Khong'],['Nang','Nong','Cao','Manh','Khong'],['Am u','Nong','Cao','Yeu','Co'],['Mua','Vua','Cao','Yeu','Co'],['Mua','Mat','Binh thuong','Yeu','Co'],['Mua','Mat','Binh thuong','Manh','Khong'],['Am u','Mat','Binh thuong','Manh','Co'],['Nang','Vua','Cao','Yeu','Khong'],['Nang','Mat','Binh thuong','Yeu','Co'],['Mua','Vua','Binh thuong','Yeu','Co']];$('#content').innerHTML=note('ID3 bổ sung từ notebook; không xuất hiện trong 5 ảnh đề. Cột cuối là nhãn. Thuộc tính dạng phân loại; chọn Gain lớn nhất, hòa thì giữ thứ tự cột.')+`<label>CSV · Dòng đầu là tên cột<textarea id="csv" rows="12">${['Troi,Nhiet_do,Do_am,Gio,Ket_qua',...rows.map(r=>r.join(','))].join('\n')}</textarea></label><button class="primary" id="id3run">Dựng cây ID3 ↗</button><div id="output" aria-live="polite"></div>`;$('#id3run').onclick=()=>guarded(()=>{const all=$('#csv').value.trim().split('\n').map(r=>r.split(',').map(x=>x.trim())),headers=all.shift();if(headers.length<2||headers.length>12||new Set(headers).size!==headers.length||all.length<1||all.length>200||all.some(r=>r.length!==headers.length||r.some(x=>!x))||headers.some(x=>!x))throw Error('CSV cần 2–12 cột có tên khác nhau, 1–200 mẫu; mỗi dòng đủ cột và không để trống.');const tree=C.id3(all,headers);let details='';function node(n,path){if('leaf'in n)return`<li><b>→ ${esc(n.leaf)}</b> (${n.n} mẫu)</li>`;details+=`<details open><summary>${esc(path)} · ${n.n} mẫu · H = ${f(n.h)}</summary>`+table(['Thuộc tính','Gain'],n.gains.map(g=>[esc(g.name),f(g.gain)]))+note('Chọn '+esc(n.attribute)+' có Gain lớn nhất.')+table(['Nhánh','Số mẫu','Entropy nhánh'],n.gains[0].groups.map(g=>[esc(g.value),g.n,f(g.h)]))+'</details>';return`<li><b>${esc(n.attribute)}</b><ul>${n.branches.map(b=>`<li>${esc(b.value)}<ul>${node(b.node,path+' / '+n.attribute+'='+b.value)}</ul></li>`).join('')}</ul></li>`}const diagram=node(tree,'Gốc');$('#output').innerHTML=formula('H(D) = −Σpᵢ log₂pᵢ; Gain(D,A) = H(D) − Σᵥ |Dᵥ|/|D| × H(Dᵥ).')+heading('1','Cây quyết định')+`<div class="tree"><ul>${diagram}</ul></div>`+heading('2','Chi tiết từng nút')+details});$('#id3run').click()}
$('#print').onclick=()=>{document.querySelectorAll('details').forEach(d=>d.open=true);window.print()};render();
